class Combatant {
  constructor(name, hp, speed) { this.name = name; this.hp = hp; this.speed = speed; this.status = []; }
  damage(n) { this.hp = Math.max(0, this.hp - n); }
  heal(n) { this.hp += n; }
  isStunned() { return this.status.includes('stun'); }
  applyStatus(s) { this.status.push(s); }
  tick() { this.status = this.status.filter(s => s !== 'stun'); } // stun lasts one turn
}

class CombatSystem {
  constructor(combatants) { this.combatants = combatants.sort((a, b) => b.speed - a.speed); this.turn = 0; }
  log(msg) { console.log(msg); }
  attack(attacker, defender, dmg) { if (defender.isStunned()) { this.log(defender.name + ' is stunned and takes no damage.'); return; } defender.damage(dmg); this.log(attacker.name + ' hits ' + defender.name + ' for ' + dmg + ' HP (' + defender.hp + ' left).'); }
  applyPoison(target, amt) { target.applyStatus('poison'); this.log(target.name + ' is poisoned (' + amt + ' per turn).'); }
  tickPoisons() { for (const c of this.combatants) if (c.status.includes('poison')) { c.damage(3); this.log(c.name + ' takes 3 poison damage (' + c.hp + ' left).'); } }
  turnOrder() { return this.combatants.map(c => c.name); }
  runTurn() {
    const a = this.combatants[this.turn % this.combatants.length];
    const t = this.combatants[(this.turn + 1) % this.combatants.length];
    if (a.isStunned()) { this.log(a.name + ' is stunned and skips their turn.'); } else { this.attack(a, t, 10); }
    this.tickPoisons();
    for (const c of this.combatants) c.tick();
    this.turn++;
  }
  isOver() { return this.combatants.some(c => c.hp <= 0); }
}

// --- self-checking demo ---
const alice = new Combatant('Alice', 50, 70);
const bob = new Combatant('Bob', 60, 60);
const combat = new CombatSystem([alice, bob]);

console.log('INIT:', combat.turnOrder().join(' -> '));
combat.runTurn();      // Alice attacks Bob
combat.runTurn();      // Bob attacks Alice
combat.applyPoison(bob, 3);
combat.runTurn();      // Alice attacks Bob again, Bob takes poison
combat.runTurn();      // Bob attacks Alice, Alice takes poison
bob.applyStatus('stun');
combat.runTurn();      // Alice attacks Bob, Bob is stunned and misses
combat.runTurn();      // Bob attacks Alice again, Alice takes poison

assert(alice.hp === 28, 'Alice has taken poison damage over turns.');
assert(bob.hp === 24, 'Bob has taken poison damage and an attack.');
assert(!bob.isStunned(), 'Bob is no longer stunned after the turn.');
assert(combat.turn === 6, 'Six turns have passed.');

while (!combat.isOver()) combat.runTurn();
const winner = combat.combatants.find(c => c.hp > 0).name;
console.log('Combat over, ' + winner + ' wins!');
assert(winner === 'Alice', 'Alice should survive to victory.');

console.log('OK');
