class Quest {
  constructor(id, title, steps, reward) {
    this.id = id; this.title = title; this.steps = steps; this.reward = reward;
    this.progress = Array(steps.length).fill(false);
    this.completed = false;
  }
  step(index) {
    if (index < 0 || index >= this.steps.length || this.completed) return false;
    this.progress[index] = true;
    if (this.progress.every((s) => s)) this.completed = true;
    return true;
  }
}

class QuestLog {
  constructor(quests) { this.quests = quests; this.active = null; }
  start(id) {
    const q = this.quests.find((q) => q.id === id);
    if (!q || this.active) return false;
    this.active = q; return true;
  }
  progress(index) {
    if (!this.active) return false;
    const ok = this.active.step(index);
    if (ok && this.active.completed) console.log(`Quest "${this.active.title}" completed! Reward: ${this.active.reward}`);
    return ok;
  }
  getProgress() {
    if (!this.active) return [];
    return this.active.progress.map((s, i) => ({ step: this.active.steps[i], done: s }));
  }
}

const log = new QuestLog([
  new Quest('1', 'Find the Key', ['left room', 'right room', 'basement'], 'treasure chest'),
  new Quest('2', 'Defeat the Boss', ['kill goblin', 'kill ogre', 'boss fight'], 'legendary weapon'),
]);

assert(log.start('1'), 'quest starts');
assert(log.progress(0), 'step 1 completes');
assert(log.progress(1), 'step 2 completes');
assert(!log.progress(2), 'cannot skip a step');
assert(log.progress(2), 'step 3 completes');
assert(log.active.completed, 'quest is now completed');
assert(log.getProgress().every((s) => s.done), 'all steps are marked done');
