class Market {
  constructor(base){this.base=base;this.stock=new Map();}
  setStock(id,u){this.stock.set(id,u);} units(id){const u=this.stock.get(id);return u==null?50:u;}
  price(id){const base=this.base[id]||1; const demand=50-this.units(id); return Math.max(1,Math.round(base*(1+demand/50))); }
}
class Store {
  constructor(w,m,i){this.wallet=w;this.market=m;this.inv=i;}
  buy(id,q){const cost=this.market.price(id)*q;const paid=cost; if(!this.wallet.debit(paid))return {ok:false,paid}; this.inv.add(id,q); this.market.setStock(id,this.market.units(id)-q); return {ok:true,paid};}
  sell(id,q){if(!this.inv.remove(id,q))return {ok:false}; const gain=this.market.price(id)*q; this.wallet.credit(gain); this.market.setStock(id,this.market.units(id)+q); return {ok:true,gain};}
}
