class Example extends Phaser.Scene
{
    player;
    cursors;
    bullets;
    enemies;
    angle = 0;
    speed = 2;
    timeToFire = 0;

    create ()
    {
        this.player = this.add.rectangle(480, 300, 32, 32, 0xffcc44);

        this.bullets = this.add.group({
            classType: Phaser.GameObjects.Rectangle,
            defaultKey: 'bullet',
            maxSize: 30,
            runChildUpdate: true
        });

        this.enemies = this.add.group({
            classType: Phaser.GameObjects.Rectangle,
            defaultKey: 'enemy',
            maxSize: 30,
            runChildUpdate: true
        });

        for (let i = 0; i < 10; i++)
        {
            const enemy = this.enemies.get(Phaser.Math.Between(10, 950), Phaser.Math.Between(10, 550));
            enemy.setSize(20, 20);
            enemy.setFillStyle(0x00ff00);
        }

        this.cursors = this.input.keyboard.createCursorKeys();
    }

    update ()
    {
        if (this.cursors.left.isDown)
        {
            this.angle += 0.02;
        }
        else if (this.cursors.right.isDown)
        {
            this.angle -= 0.02;
        }

        this.player.rotation = this.angle;

        if (this.time.now > this.timeToFire && this.cursors.space.isDown)
        {
            this.timeToFire = this.time.now + 200;

            const bullet = this.bullets.get(this.player.x, this.player.y);
            bullet.setSize(8, 8);
            bullet.setFillStyle(0xff0000);

            const dx = Math.cos(this.angle) * 6;
            const dy = Math.sin(this.angle) * 6;

            bullet.setVelocity(dx, dy);
        }

        this.bullets.children.iterate((child) =>
        {

            child.x += child.velocityX;
            child.y += child.velocityY;

            if (child.x < -50 || child.x > 950 || child.y < -50 || child.y > 550)
            {
                child.destroy();
            }

        });

        Phaser.Geom.Intersects.RectangleToRectangle(this.player, this.enemies);

        this.enemies.children.iterate((child) =>
        {

            if (child.active)
            {
                Phaser.Geom.Intersects.RectangleToRectangle(child, this.player);

                if (!child.active)
                {
                    console.log('Game Over!');
                }
            }

        });
    }
}

