class Inventory:
	var capacity: int
	var items: Dictionary = {}

	func _init(c: int):
		capacity = c

	func add(item: String, weight: int) -> bool:
		if weight + total_weight() > capacity:
			return false
		items[item] = weight
		return true

	func remove(item: String) -> int:
		var w := items[item]
		if w != null:
			items.erase(item)
		return w or 0

	func total_weight() -> int:
		var t: int = 0
		for _, w in items:
			t += w
		return t

